(6793418, 1019562, 138630, '<td valign="top">Love the setting, the tones and processing, the figure and pose.  One of my top 10.  Voted earlier.</td>', 'Love the setting, the tones and processing, the figure and pose.  One of my top 10.  Voted earlier.', '2012-06-12 23:27:15.000000', NULL, 1),
(6793421, 1019283, 138630, '<td valign="top">A beautiful scenic and clearly shows the end - I particularly like the outcropping of rock on the right, a very well chosen perspective for the challenge.  One of my top 10.  Voted earlier.</td>', 'A beautiful scenic and clearly shows the end - I particularly like the outcropping of rock on the right, a very well chosen perspective for the challenge.  One of my top 10.  Voted earlier.', '2012-06-12 23:28:18.000000', NULL, 1),
(6793422, 1019459, 138630, '<td valign="top">Excellent idea - the rough stone wall is very effective.  The vignette is a bit strong for me but does give this that pinhole effect that works with the challenge.  One of my top 10.  Voted earlier.</td>', 'Excellent idea - the rough stone wall is very effective.  The vignette is a bit strong for me but does give this that pinhole effect that works with the challenge.  One of my top 10.  Voted earlier.', '2012-06-12 23:30:18.000000', NULL, 1),
